<div class="table-responsive panel table-panel"><table class="table"><thead><tr><th>Reference</th><th>Dormitory</th><?php if (current_user()['role']==='admin'): ?><th>Student</th><?php endif; ?><th>Method</th><th>Simulated amount</th><th>Status</th><th>Date (PHT)</th></tr></thead><tbody><?php foreach ($transactions as $t): ?><tr><td><?= e($t['reference']) ?></td><td><?= e($t['dormitory']) ?></td><?php if (current_user()['role']==='admin'): ?><td><?= e($t['student']) ?></td><?php endif; ?><td><?= e(ucfirst($t['payment_method'])) ?></td><td><?= money($t['amount']) ?></td><td><span class="status-badge <?= $t['status']==='failed' ? 'rejected' : '' ?>"><?= e($t['status']) ?></span></td><td><?= e($t['created_at']) ?></td></tr><?php endforeach; ?><?php if (!$transactions): ?><tr><td colspan="7">No simulated transactions found.</td></tr><?php endif; ?></tbody></table></div>
